      }
      return thread.gateRounds < (route.maxRounds ?? DEFAULT_GATE_MAX_ROUNDS)
        ? { ...base, decision: "loop", round: thread.gateRounds + 1, routeTo: route.to }
        : { ...base, decision: "cap-breach" };
