/** The repo top level: first ancestor holding a `.git` entry (dir, or file in a worktree). */
const gitTopLevel = (start: string): string | undefined => {
  for (let dir = start; ; dir = NodePath.dirname(dir)) {
    if (NodeFS.existsSync(NodePath.join(dir, ".git"))) return dir;
    if (NodePath.dirname(dir) === dir) return undefined;
