/** Nearest `.t3code/roles/` from `start` up to the repo top level; `start` alone outside a repo. */
const findOverlayDir = (start: string): string | undefined => {
  const top = gitTopLevel(NodePath.resolve(start)) ?? NodePath.resolve(start);
  for (let dir = NodePath.resolve(start); ; dir = NodePath.dirname(dir)) {
    const candidate = NodePath.join(dir, OVERLAY_DIR);
    if (NodeFS.existsSync(candidate)) return candidate;
    if (dir === top) return undefined;
  }
